import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.BZohXCq9.js";const b=JSON.parse('{"title":"Wiggles","description":"","frontmatter":{"title":"Wiggles"},"headers":[],"relativePath":"wiggles.md","filePath":"wiggles.md"}'),i={name:"wiggles.md"};function h(l,t,s,o,n,g){return a(),r("div",null,[...t[0]||(t[0]=[d('<h2 id="christmas-2021" tabindex="-1">Christmas 2021 <a class="header-anchor" href="#christmas-2021" aria-label="Permalink to &quot;Christmas 2021&quot;">​</a></h2><p>The Christmas 2021 was the first farming and friends event. Released on the 21st of December, 2021. To gain rewards, you had to chop down Balsam trees and redeem them for points. 1 Balsam log rewarded 2 points and 1 Balsam tree cut down to 2 logs, meaning 1 tree granted 4 points. You had an infinite supply of Balsam seed boxes available to take and plant. Redeeming the logs would put points towards a pass which had 3 levels, a free pass, and 2 passes locked away via robux, 1 being 100 robux, and the other being 200 robux. You has to complete all 3 passes to gain access to the ultimate prize, being the Sleigh, which is now a highly wanted vehicle among the community.</p><h3 id="available-rewards" tabindex="-1">Available Rewards <a class="header-anchor" href="#available-rewards" aria-label="Permalink to &quot;Available Rewards&quot;">​</a></h3><h4 id="vehicles" tabindex="-1">Vehicles <a class="header-anchor" href="#vehicles" aria-label="Permalink to &quot;Vehicles&quot;">​</a></h4><table tabindex="0"><thead><tr><th>image</th><th>name</th><th style="text-align:right;">equipment type</th></tr></thead><tbody><tr><td></td><td>📦Automatic Flatbed</td><td style="text-align:right;">BoxTrailer</td></tr><tr><td></td><td>🥛 Sl Medium</td><td style="text-align:right;">MilkTruck</td></tr><tr><td>![FarmCo Crop Pallets](/images/Screenshot 2026-09-21 211741)</td><td>🚜 Sleigh</td><td style="text-align:right;">Tractor</td></tr><tr><td></td><td>🛻 ATM700</td><td style="text-align:right;">UtilityTruck</td></tr></tbody></table><h4 id="seeds" tabindex="-1">Seeds <a class="header-anchor" href="#seeds" aria-label="Permalink to &quot;Seeds&quot;">​</a></h4><table tabindex="0"><thead><tr><th>image</th><th>name</th><th style="text-align:right;">seed type</th></tr></thead><tbody><tr><td></td><td>🌲 Balsam</td><td style="text-align:right;">tree</td></tr><tr><td></td><td>🍬 CandyCane</td><td style="text-align:right;">regular</td></tr></tbody></table><h2 id="christmas-2023" tabindex="-1">Christmas 2023 <a class="header-anchor" href="#christmas-2023" aria-label="Permalink to &quot;Christmas 2023&quot;">​</a></h2><p>The 2023 Christmas event begun on the 22nd of December 2023 and was one of the most popular events of all time, bringing out several high demand vehicles. This event ran off a similar basis as the 2021 Christmas event. You were given 3 free boxes of holly every day per Roblox account. You could plant, harvest and redeem the holly for points towards the event pass. There were only 2 passes this year, 1 being free and the other which costed 800 robux to unlock.</p><h3 id="available-rewards-1" tabindex="-1">Available Rewards <a class="header-anchor" href="#available-rewards-1" aria-label="Permalink to &quot;Available Rewards&quot;">​</a></h3><h4 id="vehicles-1" tabindex="-1">Vehicles <a class="header-anchor" href="#vehicles-1" aria-label="Permalink to &quot;Vehicles&quot;">​</a></h4><table tabindex="0"><thead><tr><th>image</th><th>name</th><th style="text-align:right;">equipment type</th></tr></thead><tbody><tr><td></td><td>🛻 Solid Hauler 4700</td><td style="text-align:right;">FlatbedTruck</td></tr><tr><td></td><td>🛻 Maverick 430</td><td style="text-align:right;">Truck</td></tr><tr><td></td><td>🚜 Vertra 135</td><td style="text-align:right;">Tractor</td></tr><tr><td></td><td>🚚 Euro Hauler 1280</td><td style="text-align:right;">SemiTruck</td></tr><tr><td></td><td>🛻 Solid Hauler 47</td><td style="text-align:right;">Truck</td></tr></tbody></table><h4 id="seeds-1" tabindex="-1">Seeds <a class="header-anchor" href="#seeds-1" aria-label="Permalink to &quot;Seeds&quot;">​</a></h4><table tabindex="0"><thead><tr><th>image</th><th>name</th><th style="text-align:right;">seed type</th></tr></thead><tbody><tr><td></td><td>Holly</td><td style="text-align:right;">regular</td></tr><tr><td></td><td>Mint</td><td style="text-align:right;">regular</td></tr><tr><td></td><td>Marshmallow</td><td style="text-align:right;">regular</td></tr><tr><td></td><td>Poinsettia</td><td style="text-align:right;">regular</td></tr></tbody></table><h4 id="wraps" tabindex="-1">Wraps <a class="header-anchor" href="#wraps" aria-label="Permalink to &quot;Wraps&quot;">​</a></h4><h2 id="christmas-2024" tabindex="-1">Christmas 2024 <a class="header-anchor" href="#christmas-2024" aria-label="Permalink to &quot;Christmas 2024&quot;">​</a></h2><p>The 2024 Christmas event was released on the 21st of December. It had 2 passes, 1 being free and the other requiring a robux fee to do. It costed 820 robux. To gain xp towards the pass, you had to redeem regular farm items, being eggs, milk, sugarcane, and wheat. This is also the update which changed the name of the bamboo seed box. The items gave xp as such: Egg box = 50 points Milk = 25 points 50 Sugar Cane = 100 points 50 Wheat = 25 points</p><h3 id="available-rewards-2" tabindex="-1">Available Rewards <a class="header-anchor" href="#available-rewards-2" aria-label="Permalink to &quot;Available Rewards&quot;">​</a></h3><h4 id="vehicles-2" tabindex="-1">Vehicles <a class="header-anchor" href="#vehicles-2" aria-label="Permalink to &quot;Vehicles&quot;">​</a></h4><table tabindex="0"><thead><tr><th>image</th><th>name</th><th style="text-align:right;">equipment type</th></tr></thead><tbody><tr><td></td><td>🚜 GD 8R410</td><td style="text-align:right;">Tractor</td></tr><tr><td></td><td>🌾NA CR10</td><td style="text-align:right;">Combine</td></tr></tbody></table><h4 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Item Type</th><th>name</th><th style="text-align:right;">quantity</th></tr></thead><tbody><tr><td>Boost</td><td>🛩️Crop Duster</td><td style="text-align:right;">x12</td></tr><tr><td>Boost</td><td>🐔Animal Boost</td><td style="text-align:right;">x8</td></tr><tr><td>Boost</td><td>💰Boost Sell Price</td><td style="text-align:right;">x16</td></tr><tr><td>Boost</td><td>🌧️Make it Rain</td><td style="text-align:right;">x4</td></tr><tr><td>Currency</td><td>💵Bonds</td><td style="text-align:right;">x350</td></tr></tbody></table><h2 id="christmas-2025" tabindex="-1">Christmas 2025 <a class="header-anchor" href="#christmas-2025" aria-label="Permalink to &quot;Christmas 2025&quot;">​</a></h2><p>The Christmas 2025 event started on the 17th of December. The pass included 2 different passes. 1 regular and 1 costing robux. The robux pass costed 999 robux to unlock. To earn xp towards the pass, there was a minigame named &#39;Sheep Shenanigans&#39; Which was a minigame about sheering different coloured sheep and putting their different coloured wool into boxes to fulfill orders. The more orders completed, the more xp you would gain. There was also an advent calendar. This is the first time an event includes a calendar which rewarded a new decoration item each day until the final day which gave the player a Christmas Tree.</p><h3 id="available-rewards-3" tabindex="-1">Available Rewards <a class="header-anchor" href="#available-rewards-3" aria-label="Permalink to &quot;Available Rewards&quot;">​</a></h3><h4 id="vehicles-3" tabindex="-1">Vehicles <a class="header-anchor" href="#vehicles-3" aria-label="Permalink to &quot;Vehicles&quot;">​</a></h4><table tabindex="0"><thead><tr><th>image</th><th>name</th><th style="text-align:right;">equipment type</th></tr></thead><tbody><tr><td></td><td>🚚 Euro Hauler 1280</td><td style="text-align:right;">SemiTruck</td></tr><tr><td></td><td>🛻 Maverick 430 x2</td><td style="text-align:right;">Truck</td></tr><tr><td></td><td>🛻Solid Hauler 47</td><td style="text-align:right;">Truck</td></tr><tr><td></td><td>🚜GD 8R410 x2</td><td style="text-align:right;">Tractor</td></tr><tr><td></td><td>🛻R500 x4</td><td style="text-align:right;">Truck</td></tr><tr><td></td><td>🚜 Vintage Tractor x2</td><td style="text-align:right;">Tractor</td></tr><tr><td></td><td>🌾Vintage Harvester x2</td><td style="text-align:right;">Combine</td></tr></tbody></table><h4 id="other-1" tabindex="-1">Other <a class="header-anchor" href="#other-1" aria-label="Permalink to &quot;Other&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Item Type</th><th>name</th><th style="text-align:right;">quantity</th></tr></thead><tbody><tr><td>Boost</td><td>🛩️Crop Duster</td><td style="text-align:right;">x17</td></tr><tr><td>Boost</td><td>💰Boost Sell Price</td><td style="text-align:right;">x13</td></tr><tr><td>Boost</td><td>🌧️Make it Rain</td><td style="text-align:right;">x4</td></tr></tbody></table>',29)])])}const m=e(i,[["render",h]]);export{b as __pageData,m as default};
